<script setup lang="ts">
import { serverConnectionLabel } from '../serverConnection'
import { useAppScope } from '../composables/useAppScope'
import CommitHash from '../components/CommitHash.vue'
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Plus } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { errorText, http, normalizeRelease, normalizeService, payload, rows, serviceRequest } from '../api'
import type { DeploymentServer, Release, Service, ServiceEnvironment } from '../types'
import { environmentLabel, statusLabel, statusType, formatTime, timeParts, windowsCommand } from '../ui'
import MobileBuildSettings from '../components/MobileBuildSettings.vue'
import BuildEngineSelect from '../components/BuildEngineSelect.vue'
import AppIntegrationAccess from '../components/AppIntegrationAccess.vue'
import { isMobileDraft, mobileBuildDefaults, mobileBuildError, mobileFormat, mobileVersionLabel } from '../mobile'
import ServiceIdentity from '../components/ServiceIdentity.vue'
import ServiceIconPicker from '../components/ServiceIconPicker.vue'
import AppArtifactVersions from '../components/AppArtifactVersions.vue'

type EnvName='dev'|'test'|'prod'
const mobileSettings=ref<{commitParameters:()=>boolean}>()
const { apps, api, buildPath, releasePath } = useAppScope()
const route=useRoute(),router=useRouter(),id=route.params.id,loading=ref(true),saving=ref(false),tab=ref(apps?String(route.query.tab||'mobile'):'basic'),loadError=ref(''),artifacts=ref<Record<string,unknown>[]>([]),builds=ref<Release[]>([]),releases=ref<Release[]>([]),servers=ref<DeploymentServer[]>([]),activeEnv=ref<EnvName>('dev')
const artifactLoading=ref(false),artifactsLoaded=ref(false),artifactError=ref('')
let artifactRequest=0,artifactController:AbortController|undefined
const model=reactive<Service>({name:'',code:'',serviceType:'BACKEND',buildEngine:'GITHUB',imageBuildMode:'REPOSITORY_DOCKERFILE',description:'',status:true,gitUrl:'',defaultBranch:'main',buildTool:'Maven',buildCommand:'./mvnw clean package -DskipTests',jarPath:'target/*.jar',dockerfilePath:'Dockerfile',imageRepository:'',imageName:'',environment:'test',deployHost:'',deployPort:8080,containerPort:8080,envVariables:[]})
function environmentDefault(name:EnvName):ServiceEnvironment{return{environmentName:name,serverIds:[],hostPort:8080,containerPort:8080,containerName:'',envFilePath:'',dockerNetwork:'',restartPolicy:'UNLESS_STOPPED',deploymentMode:'DOCKER_RUN',composeService:'',startCommand:'',healthCheckUrl:'',envJson:'{}',envVariables:[],enabled:true}}
const environmentConfigs=reactive<Record<EnvName,ServiceEnvironment>>({dev:environmentDefault('dev'),test:environmentDefault('test'),prod:environmentDefault('prod')})
const appEnabled=computed(()=>model.status!==false&&model.status!=='DISABLED')
const isMobile=computed(()=>model.serviceType==='FLUTTER_ANDROID')
const isFrontend=computed(()=>model.serviceType==='FRONTEND')
const repositoryDockerfileMode=computed(()=>isFrontend.value&&model.imageBuildMode==='REPOSITORY_DOCKERFILE')
const currentEnvironment=computed(()=>environmentConfigs[activeEnv.value])
const selectedServers=computed(()=>currentEnvironment.value.serverIds.map(serverId=>servers.value.find(server=>String(server.id)===String(serverId))).filter(Boolean) as DeploymentServer[])
function addEnv(){currentEnvironment.value.envVariables.push({key:'',value:'',secret:false})}
function frontendCommand(tool:string){return tool==='pnpm'?'pnpm install --frozen-lockfile && pnpm run build':tool==='yarn'?'yarn install --frozen-lockfile && yarn build':'npm ci && npm run build'}
function buildToolChanged(value:string){if(isFrontend.value)model.buildCommand=frontendCommand(value);else model.buildCommand=value==='Gradle'?'./gradlew clean build -x test':'mvn clean package -DskipTests'}
function parseEnvironment(raw:Record<string,unknown>):ServiceEnvironment{let values:Record<string,unknown>={};try{values=JSON.parse(String(raw.envJson||'{}'))}catch{}return{...environmentDefault(String(raw.environmentName) as EnvName),...raw,serverIds:Array.isArray(raw.serverIds)?raw.serverIds as Array<number|string>:[],envVariables:Object.entries(values).map(([key,value])=>({key,value:String(value??''),secret:false}))} as ServiceEnvironment}
async function load(){loading.value=true;try{const [serviceResult,serverResult,environmentResult]=await Promise.all([http.get(api(`/services/${id}`)),apps?Promise.resolve({data:[]}):http.get(api('/servers')),apps?Promise.resolve({data:[]}):http.get(api(`/services/${id}/environments`))]);Object.assign(model,normalizeService(payload<Record<string,unknown>>(serviceResult,{})));model.serviceType=model.serviceType||'BACKEND';if(apps&&model.serviceType!=='FLUTTER_ANDROID')throw new Error('该应用不存在或无 App 访问权限');loadError.value='';if(isMobile.value)model.mobileBuild={...mobileBuildDefaults(),...model.mobileBuild};servers.value=rows<DeploymentServer>(serverResult.data);for(const raw of rows<Record<string,unknown>>(environmentResult.data)){const config=parseEnvironment(raw);if(['dev','test','prod'].includes(config.environmentName))Object.assign(environmentConfigs[config.environmentName],config)}}catch(e){loadError.value=errorText(e);ElMessage.error(loadError.value)}finally{loading.value=false}}
async function loadArtifacts(force=false){
  if(artifactLoading.value||artifactsLoaded.value&&!force)return
  const request=++artifactRequest;artifactController?.abort();const controller=new AbortController();artifactController=controller
  artifactLoading.value=true;artifactError.value=''
  try{
    const result=rows<Record<string,unknown>>((await http.get(api('/artifacts'),{params:{serviceId:id},signal:controller.signal})).data)
    const enriched=isMobile.value?await Promise.all(result.map(async item=>{try{return {...item,...payload<Record<string,unknown>>(await http.get(api(`/mobile/artifacts/${item.id}`),{signal:controller.signal}),{}),id:item.id}}catch{return {...item,_detailsUnavailable:true}}})):result
    if(request!==artifactRequest)return
    artifacts.value=enriched;artifactsLoaded.value=true
  }catch(error){if(request!==artifactRequest)return;artifacts.value=[];artifactsLoaded.value=false;artifactError.value=errorText(error,'暂时无法读取安装包版本')}
  finally{if(request===artifactRequest)artifactLoading.value=false}
}
async function loadTab(name:string){if(name==='artifacts')await loadArtifacts();if(name==='builds'&&!builds.value.length)try{builds.value=rows<Record<string,unknown>>((await http.get(api('/builds'),{params:{serviceId:id}})).data).map(normalizeRelease)}catch(error){ElMessage.error(errorText(error,'读取历史记录失败'))};if(name==='releases'&&!releases.value.length)try{releases.value=rows<Record<string,unknown>>((await http.get(api('/releases'),{params:{serviceId:id}})).data).map(normalizeRelease)}catch(error){ElMessage.error(errorText(error,'读取历史记录失败'))}}
function tabChanged(name: string | number){loadTab(String(name));if(apps)router.replace({query:{...route.query,tab:String(name)}})}
async function save(){if(saving.value||loading.value||loadError.value)return;if(isMobile.value&&mobileSettings.value&&!mobileSettings.value.commitParameters())return;if((!repositoryDockerfileMode.value&&windowsCommand(model.buildCommand))||windowsCommand(model.workDirectory))return ElMessage.warning('构建运行在 Linux 服务器，请改用 Linux 命令和相对路径');if(isMobile.value&&(!apps||appEnabled.value)){const reason=mobileBuildError(model.mobileBuild);if(reason)return ElMessage.warning(reason)}saving.value=true;try{await http.put(api(`/services/${id}`),serviceRequest(model));if(!isMobile.value)for(const name of ['dev','test','prod'] as EnvName[]){const config=environmentConfigs[name],env=Object.fromEntries(config.envVariables.filter(v=>v.key).map(v=>[v.key,v.value]));await http.put(api(`/services/${id}/environments/${name}`),{...config,serverIds:config.serverIds.map(Number),envJson:JSON.stringify(env)})}ElMessage.success(isMobile.value?'App 服务配置已保存':'服务与三套环境配置已保存')}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
onBeforeUnmount(()=>{++artifactRequest;artifactController?.abort()})
onMounted(async()=>{await load();if(!loadError.value)await loadTab(tab.value)})
</script>

<template>
  <div class="page-head"><div style="min-width:0"><el-button link :icon="ArrowLeft" @click="router.push(apps?'/apps':'/services')">{{apps?'返回 App 发布':'返回服务列表'}}</el-button><h2 style="margin-top:14px"><ServiceIdentity :service="model" large/></h2><p>{{model.description||(apps?'配置应用、构建安装包并追踪各环境交付。':'管理代码仓库、构建方式与部署环境。')}}</p></div><div class="actions"><el-button v-if="apps" :disabled="loading||!!loadError||!appEnabled||!!mobileBuildError(model.mobileBuild)" @click="router.push(`/apps/${id}/build`)">新建构建</el-button><el-button type="primary" :loading="saving" :disabled="loading||!!loadError" @click="save">{{apps&&!appEnabled?'保存配置草稿':'保存配置'}}</el-button></div></div>
  <el-alert v-if="loadError" :title="loadError" type="error" :closable="false" show-icon/><section v-else class="panel" v-loading="loading">
    <el-alert v-if="!loading && isMobileDraft(model)" class="mobile-draft-notice" title="待配置（未启用）" description="已登记代码仓库。请在 App 构建配置中补充固定 Flutter 版本，并完成至少一个环境的包名和签名配置；完成配置并启用后，才能选择此服务打包。" type="info" :closable="false" show-icon style="margin-bottom:20px"/>
    <el-tabs v-model="tab" @tab-change="tabChanged">
      <el-tab-pane label="基础信息配置" name="basic"><div class="form-section"><h4>基础信息</h4><el-form label-position="top"><el-form-item label="服务图标"><ServiceIconPicker v-model="model.displayIcon" :service-type="model.serviceType" :code="model.code"/></el-form-item><div class="two"><el-form-item label="服务名称"><el-input v-model="model.name"/></el-form-item><el-form-item label="服务标识"><el-input v-model="model.code" disabled/></el-form-item></div><el-form-item label="服务描述"><el-input v-model="model.description" type="textarea" :rows="3"/></el-form-item><el-form-item><el-switch v-model="model.status" :active-text="apps?'启用 App 构建':'启用服务'"/><p v-if="apps" class="field-help">启用前需完成 Flutter 和至少一个环境的包名与签名配置；未启用时可保存草稿。</p></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane label="Git 配置" name="git"><div class="form-section"><h4>代码仓库</h4><el-form label-position="top"><el-form-item label="仓库地址"><el-input v-model="model.gitUrl" placeholder="git@github.com:team/project.git"/></el-form-item><div class="two"><el-form-item label="默认分支"><el-input v-model="model.defaultBranch"/></el-form-item><el-form-item label="认证方式"><el-select v-model="model.gitAuthType" style="width:100%"><el-option label="SSH Key" value="SSH"/><el-option label="Access Token" value="TOKEN"/><el-option label="用户名密码" value="PASSWORD"/></el-select></el-form-item></div><el-form-item label="凭据标识"><el-input v-model="model.gitCredential" placeholder="敏感凭据由后端加密保存" show-password/></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane v-if="!isMobile" label="构建配置" name="build"><div class="form-section"><h4>{{isFrontend?'Node 前端构建':'Spring Boot JAR 构建'}}</h4><el-form label-position="top"><BuildEngineSelect v-model="model.buildEngine" :disabled="loading||saving"/><el-alert v-if="repositoryDockerfileMode" title="当前由仓库 Dockerfile 完成依赖安装和应用构建，平台不会在宿主机重复执行下方 Node 构建命令。" type="info" :closable="false" show-icon style="margin-bottom:16px"/><div class="two"><el-form-item :label="isFrontend?'包管理器':'构建工具'"><el-select v-model="model.buildTool" style="width:100%" :disabled="repositoryDockerfileMode" @change="buildToolChanged"><template v-if="isFrontend"><el-option label="npm" value="npm"/><el-option label="pnpm" value="pnpm"/><el-option label="yarn" value="yarn"/></template><template v-else><el-option label="Maven" value="Maven"/><el-option label="Gradle" value="Gradle"/></template></el-select></el-form-item><el-form-item v-if="!isFrontend" label="Java 版本"><el-input model-value="Java 21（平台构建环境）" disabled/></el-form-item><el-form-item v-else label="运行环境"><el-input :value="repositoryDockerfileMode?'由仓库 Dockerfile 决定':'Node.js 22（平台构建环境）'" disabled/></el-form-item></div><el-alert v-if="(!repositoryDockerfileMode&&windowsCommand(model.buildCommand)) || windowsCommand(model.workDirectory)" title="检测到 Windows 命令或路径，请改为 Linux 配置后保存。" type="warning" :closable="false" show-icon style="margin-bottom:16px"/><el-form-item label="构建命令"><el-input v-model="model.buildCommand" class="mono" :disabled="repositoryDockerfileMode" :placeholder="isFrontend?'npm ci && npm run build':'mvn clean package -DskipTests'"/></el-form-item><div class="two"><el-form-item label="工作目录"><el-input v-model="model.workDirectory" :disabled="repositoryDockerfileMode" placeholder="默认仓库根目录，例如 frontend"/></el-form-item><el-form-item :label="isFrontend?'输出目录':'JAR 匹配路径'"><el-input v-model="model.jarPath" :disabled="repositoryDockerfileMode" :placeholder="isFrontend?'dist':'target/*.jar'"/></el-form-item></div><el-form-item label="构建超时（分钟）"><el-input-number v-model="model.buildTimeout" :min="1" :max="180"/></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane v-if="!isMobile" label="镜像配置" name="image"><div class="form-section"><h4>容器镜像</h4><el-form label-position="top"><el-form-item v-if="isFrontend" label="前端交付方式" required><el-radio-group v-model="model.imageBuildMode"><el-radio-button value="STATIC_NGINX">静态站点（Nginx）</el-radio-button><el-radio-button value="REPOSITORY_DOCKERFILE">Node 应用（仓库 Dockerfile）</el-radio-button></el-radio-group><div class="field-help">已有前端默认保持“静态站点”；只有需要持续运行 Node、服务端渲染或提供接口的项目才选择“Node 应用”。</div></el-form-item><el-alert v-if="repositoryDockerfileMode" title="平台将直接使用仓库 Dockerfile，并固定以源码根目录作为 docker build 上下文。" type="info" :closable="false" show-icon style="margin-bottom:16px"/><el-alert v-else-if="isFrontend" title="平台保持现有链路：先生成静态文件，再自动制作 Nginx 镜像。" type="info" :closable="false" show-icon style="margin-bottom:16px"/><el-form-item label="完整镜像仓库地址"><el-input v-model="model.imageRepository" placeholder="registry.example.com/team/service-name"/></el-form-item><div class="two"><el-form-item label="镜像名称"><el-input v-model="model.imageName" :placeholder="model.code"/></el-form-item><el-form-item label="Dockerfile 路径"><el-input v-model="model.dockerfilePath" :disabled="isFrontend&&!repositoryDockerfileMode" placeholder="Dockerfile"/><div class="muted" style="margin-top:6px">{{repositoryDockerfileMode?'相对源码根目录填写，例如 Dockerfile 或 deploy/Dockerfile。':isFrontend?'静态模式由平台生成 Dockerfile，无需调整。':'相对工作目录填写。'}}</div></el-form-item></div><el-alert title="镜像仓库认证由平台基础配置统一管理。" type="info" :closable="false" show-icon/></el-form></div></el-tab-pane>
      <el-tab-pane v-if="isMobile" label="App 构建配置" name="mobile"><div class="form-section"><h4>Flutter Android · {{mobileFormat(model.mobileBuild)==='APK'?'完整 APK':'AAB'}}</h4><el-form label-position="top"><BuildEngineSelect v-model="model.buildEngine" :disabled="loading||saving"/><MobileBuildSettings v-if="model.mobileBuild" ref="mobileSettings" :model="model.mobileBuild"/><el-form-item label="项目工作目录"><el-input v-model="model.workDirectory" placeholder="默认仓库根目录"/></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane v-if="isMobile" label="发布环境" name="mobile-environments"><div class="form-section"><h4>按环境交付安装包</h4><p class="artifact-storage-note">构建时选择开发、预生产或生产，安装包只能交付到相同环境。包名、签名和地址随构建锁定，每条发布记录独立拉取并确认结果。</p><el-table :data="[{name:'开发',merge:'不合并'},{name:'预生产',merge:'不合并'},{name:'生产',merge:'启用自动合回时，发布成功后合并已验证的提交'}]"><el-table-column prop="name" label="发布环境"/><el-table-column label="交付方式"><template #default>拉取安装包，再确认实际发布结果</template></el-table-column><el-table-column prop="merge" label="代码合回"/></el-table><p class="artifact-storage-note">在“App 构建配置”中分别配置并启用环境。历史包若未记录构建环境，需要重新构建后才能创建新交付。生产发布仍需当前登录账号的动态码确认；下载完成不会自动标记发布成功。</p></div></el-tab-pane>
      <el-tab-pane v-if="isMobile" label="接口对接" name="integration"><AppIntegrationAccess v-if="tab==='integration' && String(model.id)===String(route.params.id)" :key="String(route.params.id)" :service-id="String(route.params.id)" :service-name="model.name"/></el-tab-pane>
      <el-tab-pane v-if="!isMobile" label="环境与集群" name="deploy">
        <div class="environment-layout">
          <div class="environment-head"><div><h4>部署环境</h4><p>每个环境都是一个集群，可以绑定一台或多台服务器。</p></div><el-button :icon="Plus" @click="router.push('/servers')">管理服务器</el-button></div>
          <el-tabs v-model="activeEnv" type="card" class="environment-tabs">
            <el-tab-pane label="开发环境" name="dev"/><el-tab-pane label="预生产环境" name="test"/><el-tab-pane label="生产环境" name="prod"/>
          </el-tabs>
          <el-form label-position="top" class="environment-form">
            <div class="environment-status"><div><b>{{activeEnv==='dev'?'开发环境':activeEnv==='test'?'预生产环境':'生产环境'}}</b><span>已选择 {{selectedServers.length}} 个集群节点</span></div><el-switch v-model="currentEnvironment.enabled" active-text="允许发版"/></div>
            <el-form-item label="集群服务器" required>
              <el-select v-model="currentEnvironment.serverIds" multiple filterable collapse-tags :max-collapse-tags="3" placeholder="请选择一台或多台服务器" style="width:100%">
                <el-option v-for="server in servers.filter(item=>item.enabled)" :key="server.id" :value="server.id!" :label="`${server.name} · ${serverConnectionLabel(server,{includeAuth:true})}`"/>
              </el-select>
              <div v-if="!servers.length" class="field-help">还没有服务器，请先点击右上角“管理服务器”添加。</div>
            </el-form-item>
            <div v-if="selectedServers.length" class="cluster-nodes"><div v-for="server in selectedServers" :key="server.id"><span class="status-dot status-success"></span><b>{{server.name}}</b><small>{{server.connectionMode==='SSH_CONFIG'?serverConnectionLabel(server):`${server.host} · ${server.authType==='PASSWORD'?'密码':'SSH Key'}`}}</small></div></div>
            <el-form-item label="部署方式"><el-radio-group v-model="currentEnvironment.deploymentMode"><el-radio-button value="DOCKER_RUN">直接运行容器</el-radio-button><el-radio-button value="DOCKER_COMPOSE">Docker Compose</el-radio-button></el-radio-group></el-form-item>
            <template v-if="currentEnvironment.deploymentMode==='DOCKER_RUN'">
              <el-alert type="info" :closable="false" show-icon title="平台会按容器名称删除旧容器，再使用本次选择的镜像启动同名新容器；不需要 sudo。"/>
              <div class="two" style="margin-top:18px"><el-form-item label="宿主机端口"><el-input-number v-model="currentEnvironment.hostPort" :min="1" :max="65535" style="width:100%"/></el-form-item><el-form-item label="容器端口"><el-input-number v-model="currentEnvironment.containerPort" :min="1" :max="65535" style="width:100%"/></el-form-item></div>
              <el-form-item label="容器名称" required><el-input v-model="currentEnvironment.containerName" :placeholder="model.code"/><div class="field-help">必须与服务器上原有容器名称完全一致，例如 {{model.code}}。</div></el-form-item>
              <div class="two"><el-form-item label="远程环境变量文件"><el-input v-model="currentEnvironment.envFilePath" placeholder="/srv/services/env/service.env"/><div class="field-help">留空表示不使用 --env-file，平台不会读取或修改该文件内容。</div></el-form-item><el-form-item label="Docker 网络"><el-input v-model="currentEnvironment.dockerNetwork" placeholder="service-net"/></el-form-item></div>
              <el-form-item label="容器重启策略"><el-select v-model="currentEnvironment.restartPolicy" style="width:100%"><el-option label="不自动重启（与未配置 --restart 一致）" value="NO"/><el-option label="除非手动停止，否则重启" value="UNLESS_STOPPED"/><el-option label="始终重启" value="ALWAYS"/><el-option label="异常退出时重启" value="ON_FAILURE"/></el-select></el-form-item>
            </template>
            <template v-else>
              <el-alert type="info" :closable="false" show-icon title="平台只覆盖镜像版本，Compose 中原有的环境变量、挂载目录、网络和依赖关系都会保留。"/>
              <div class="two" style="margin-top:18px"><el-form-item label="Compose 服务名" required><el-input v-model="currentEnvironment.composeService" :placeholder="model.code"/><div class="field-help">默认与服务标识一致，例如 {{model.code}}。</div></el-form-item><el-form-item label="容器内部健康检查端口"><el-input-number v-model="currentEnvironment.containerPort" :min="1" :max="65535" style="width:100%"/></el-form-item></div>
            </template>
            <el-form-item label="健康检查地址"><el-input v-model="currentEnvironment.healthCheckUrl" :placeholder="currentEnvironment.deploymentMode==='DOCKER_COMPOSE'?'例如 /healthz':'例如 http://{host}:{hostPort}/healthz'"/><div class="field-help">{{currentEnvironment.deploymentMode==='DOCKER_COMPOSE'?'平台会从服务器内找到 Compose 容器地址进行检查，不要求映射宿主机端口。':'使用 {host} 表示当前节点地址，平台会逐台检查；留空时使用默认地址。'}}</div></el-form-item>
            <div class="panel-title env-title"><div><b>环境变量</b><small>仅注入当前环境的容器</small></div><el-button :icon="Plus" @click="addEnv">添加变量</el-button></div>
            <div v-if="currentEnvironment.envVariables.length"><div v-for="(item,index) in currentEnvironment.envVariables" :key="index" class="env-row"><el-input v-model="item.key" placeholder="变量名，例如 APP_MODE"/><el-input v-model="item.value" placeholder="变量值" :type="item.secret?'password':'text'" show-password/><el-checkbox v-model="item.secret">敏感</el-checkbox><el-button link type="danger" @click="currentEnvironment.envVariables.splice(index,1)">删除</el-button></div></div>
            <div v-else class="environment-empty">当前环境暂无环境变量</div>
          </el-form>
        </div>
      </el-tab-pane>
      <el-tab-pane :label="apps?'构建记录':'打包记录'" name="builds">
        <el-table v-if="builds.length" :data="builds" class="clickable-table" @row-click="(row: Release) => router.push(buildPath(row.id))">
