          <el-table-column label="分支 / Commit" min-width="220"><template #default="{row}"><b class="record-branch" :title="row.branch">{{row.branch || '未记录分支'}}</b><CommitHash :value="row.commitId"/></template></el-table-column>
          <el-table-column v-if="isMobile" label="App 版本" min-width="160"><template #default="{row}"><b class="artifact-version-label">{{mobileVersionLabel(row)}}</b></template></el-table-column><el-table-column v-if="isMobile" label="构建环境" width="125"><template #default="{row}">{{row.environment?environmentLabel(row.environment):'历史记录未保存'}}<small class="artifact-repository">{{row.mobileBuildMode || ''}}</small></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.status)" size="small">{{statusLabel(row.status)}}</el-tag></template></el-table-column>
          <el-table-column label="打包人" min-width="100"><template #default="{row}">{{row.createdBy || '—'}}</template></el-table-column>
          <el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="router.push(buildPath(row.id))">详情</el-button></template></el-table-column>
