          <el-table-column label="打包人" width="110"><template #default="{row}">{{row.createdBy || '—'}}</template></el-table-column><el-table-column v-if="apps" label="交付" width="120"><template #default="{row}"><el-button link type="primary" :disabled="!appEnabled" @click="router.push(`/apps/${id}/release?artifactId=${row.id}`)">创建交付</el-button></template></el-table-column>
        </el-table><div v-else class="empty"><div><strong>暂无制品版本</strong><p>{{isMobile?'安装包构建、校验并归档后，会在这里保留版本记录。':'打包成功并推送镜像后，会在这里保留版本记录。'}}</p></div></div>
        </template>
      </el-tab-pane>
      <el-tab-pane :label="apps?'交付记录':'发版记录'" name="releases">
        <el-table v-if="releases.length" :data="releases" class="clickable-table" @row-click="(row: Release) => router.push(releasePath(row.id))">
          <el-table-column label="创建时间 / 任务" width="165"><template #default="{row}"><div class="record-time" :title="timeParts(row.createdAt).full"><b>{{timeParts(row.createdAt).time}}</b><span>{{timeParts(row.createdAt).date}}</span><small>#{{row.id}}</small></div></template></el-table-column>
          <el-table-column label="分支 / Commit" min-width="220"><template #default="{row}"><b class="record-branch" :title="row.branch">{{row.branch || '未记录分支'}}</b><CommitHash :value="row.commitId"/></template></el-table-column>
          <el-table-column v-if="isMobile" label="App 版本" min-width="160"><template #default="{row}"><b>{{mobileVersionLabel(row)}}</b></template></el-table-column><el-table-column label="环境" width="105"><template #default="{row}"><el-tag effect="plain" size="small" :type="row.environment === 'prod' ? 'danger' : row.environment === 'test' ? 'warning' : 'info'">{{environmentLabel(row.environment)}}</el-tag></template></el-table-column>
          <el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="statusType(row.status)" size="small">{{statusLabel(row.status)}}</el-tag></template></el-table-column>
          <el-table-column label="发布人" min-width="100"><template #default="{row}">{{row.createdBy || '—'}}</template></el-table-column>
          <el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="router.push(releasePath(row.id))">详情</el-button></template></el-table-column>
        </el-table><div v-else class="empty"><div><strong>暂无发版记录</strong><p>选择成功构建的制品，发起第一次发布。</p></div></div>
      </el-tab-pane>
    </el-tabs>
  </section>
</template>

